python3 -c "
import json, sys

with open('/work/output/artifacts/skill-flow-add-node/BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    flow = json.load(f)

errors = []

# --- 1. All node IDs are unique ---
node_ids = [n['id'] for n in flow['nodes']]
if len(node_ids) != len(set(node_ids)):
    errors.append('Duplicate node IDs')
else:
    print('OK  Node IDs are unique:', node_ids)

# --- 2. All edge IDs are unique ---
edge_ids = [e['id'] for e in flow['edges']]
if len(edge_ids) != len(set(edge_ids)):
    errors.append('Duplicate edge IDs')
else:
    print('OK  Edge IDs are unique:', edge_ids)

# --- 3. Every edge references valid node IDs ---
node_id_set = set(node_ids)
for e in flow['edges']:
    if e['sourceNodeId'] not in node_id_set:
        errors.append(f'Edge {e[\"id\"]}: sourceNodeId \"{e[\"sourceNodeId\"]}\" is not a known node')
    if e['targetNodeId'] not in node_id_set:
        errors.append(f'Edge {e[\"id\"]}: targetNodeId \"{e[\"targetNodeId\"]}\" is not a known node')
if not errors:
    print('OK  All edge endpoints reference valid nodes')

# --- 4. Check linear chain start → getWeather → convertToCelsius → formatSummary ---
edge_map = {}
for e in flow['edges']:
    edge_map[(e['sourceNodeId'], e['sourcePort'])] = (e['targetNodeId'], e['targetPort'])

def check_edge(src, src_port, expected_tgt, expected_tgt_port):
    key = (src, src_port)
    if key not in edge_map:
        errors.append(f'Missing edge from {src}:{src_port}')
        return
    tgt, tgt_port = edge_map[key]
    if tgt != expected_tgt or tgt_port != expected_tgt_port:
        errors.append(f'Edge from {src}:{src_port} → expected {expected_tgt}:{expected_tgt_port}, got {tgt}:{tgt_port}')
    else:
        print(f'OK  {src}:{src_port} → {tgt}:{tgt_port}')

check_edge('start', 'output', 'getWeather', 'input')
check_edge('getWeather', 'default', 'convertToCelsius', 'input')
check_edge('convertToCelsius', 'success', 'formatSummary', 'input')
check_edge('formatSummary', 'success', 'checkTemperature', 'input')
check_edge('checkTemperature', 'true', 'endNiceDay', 'input')
check_edge('checkTemperature', 'false', 'endBringJacket', 'input')

# --- 5. convertToCelsius node structure ---
cn = next((n for n in flow['nodes'] if n['id'] == 'convertToCelsius'), None)
if cn is None:
    errors.append('convertToCelsius node missing')
else:
    if cn['type'] != 'core.action.script':
        errors.append(f'convertToCelsius wrong type: {cn[\"type\"]}')
    script = cn['inputs']['script']
    if 'temperatureF' not in script or 'temperatureC' not in script:
        errors.append('convertToCelsius script missing temperatureF or temperatureC')
    if '(tempF - 32) * 5 / 9' not in script and '5/9' not in script:
        errors.append('convertToCelsius script missing F→C formula')
    print('OK  convertToCelsius node exists with correct type and script')
    print('    Script:', script)

# --- 6. formatSummary script references both temperatures and C value ---
fs = next((n for n in flow['nodes'] if n['id'] == 'formatSummary'), None)
if fs is None:
    errors.append('formatSummary node missing')
else:
    script = fs['inputs']['script']
    if 'convertToCelsius' not in script:
        errors.append('formatSummary script does not reference convertToCelsius')
    if 'temperatureC' not in script:
        errors.append('formatSummary script missing temperatureC output')
    if 'C' not in script:
        errors.append('formatSummary summary string does not include C')
    print('OK  formatSummary script updated:')
    print('    Script:', script)

# --- 7. Variables include convertToCelsius ---
var_ids = [v['id'] for v in flow['variables']['nodes']]
if 'convertToCelsius.output' not in var_ids:
    errors.append('variables.nodes missing convertToCelsius.output')
else:
    print('OK  convertToCelsius.output variable registered')

# --- 8. Layout includes convertToCelsius ---
if 'convertToCelsius' not in flow['layout']['nodes']:
    errors.append('layout missing convertToCelsius')
else:
    print('OK  convertToCelsius has layout entry at', flow['layout']['nodes']['convertToCelsius']['position'])

# --- 9. No orphan old edge ---
for e in flow['edges']:
    if e['sourceNodeId'] == 'getWeather' and e['targetNodeId'] == 'formatSummary':
        errors.append('Old direct edge getWeather→formatSummary still present')

print()
if errors:
    print('ERRORS:')
    for err in errors:
        print(' ', err)
    sys.exit(1)
else:
    print('All validations passed.')
"

